function drawFx(f){ctx.save();ctx.globalAlpha=Math.max(0,f.life/f.max);ctx.strokeStyle=f.color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(f.x,f.y,f.r*(1-f.life/f.max)+5,0,7);ctx.stroke();ctx.fillStyle=f.color;ctx.font='16px sans-serif';ctx.textAlign='center';ctx.fillText(f.text||'✦',f.x,f.y-f.r*(1-f.life/f.max));ctx.restore()}
function updateDeck(){const root=$('#deckList');root.innerHTML='';deck.forEach(id=>{const h=heroes.find(a=>a.id===id);if(!h)return;const count=towers.filter(t=>t.hero.id===id).length,card=document.createElement('button');card.className='hero-card'+(selected===id?' selected':'')+(count?' deployed':'');card.style.setProperty('--hero-color',h.color);card.innerHTML=`<span class="hero-avatar"><span>${h.symbol}</span></span><span class="hero-info"><b>${h.name} · ${h.title}</b><small>${h.role.split(' · ')[0]}${count?' · '+count+' DEPLOYED':''}</small></span><span class="hero-level">✦ 1</span><span class="hero-cost">✦ ${h.cost}</span>`;card.onclick=()=>{selected=id;selectedTower=null;updateDeck();showToast(`${h.name} selected · choose an open landing circle`)};root.appendChild(card)})}
function refreshHud(){$('#coins').textContent=coins;$('#lives').textContent=lives;$('#waveNum').textContent=String(wave).padStart(2,'0');$('#enemyCount').textContent=enemies.length+spawnLeft;$('#waveProgress').style.width=spawnTotal?`${Math.min(100,spawned/spawnTotal*100)}%`:'0%';$('#waveState').textContent=active?'BREACH IN PROGRESS':'PREPARE';$('#launchBtn').disabled=active;$('#launchBtn').querySelector('span').textContent=gameOver?'RETRY MISSION':active?'WAVE ACTIVE':(spawned&&spawned===spawnTotal?'NEXT WAVE':'START WAVE');$('#launchBtn').querySelector('b').innerHTML=gameOver?'↻':`${String(wave).padStart(2,'0')} <i>→</i>`;$('#abilityStatus').textContent=ability?`READY · ${ability} CHARGE`:'RECHARGING';$('#abilityBtn').disabled=ability<1||!enemies.length;$('#waveTitle').textContent=active?'Riftborn advancing':'The rift stirs';$('#waveSubtitle').textContent=active?`${enemies.length+spawnLeft} enemies remain on the trail.`:'Deploy your guardians before the first breach.';$('#objOne').classList.toggle('complete',wave>1||(!active&&spawned>0&&spawned===spawnTotal&&!enemies.length));$('#objTwo').classList.toggle('complete',lives>=10&&wave>1);document.querySelector('.objectives-heading .objective-count').textContent=`${(wave>1?1:0)+(lives>=10&&wave>1?1:0)} / 2`}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function deploy(i){const h=heroes.find(x=>x.id===selected);if(towers.some(t=>t.pad===i)){selectedTower=towers.find(t=>t.pad===i);return}if(!h||!deck.includes(h.id)){showToast('Add this guardian to your battle deck first');return}if(coins<h.cost){showToast(`Need ${h.cost-coins} more stardust`);return}coins-=h.cost;towers.push({hero:h,pad:i,level:1,cool:0});selectedTower=null;playTone(480,.09);updateDeck();refreshHud();showToast(`${h.name} deployed · ${h.title}`)}
function startWave(){if(gameOver){coins=300;lives=20;wave=1;active=false;spawnLeft=spawned=spawnTotal=0;enemies=[];towers=[{hero:heroes[0],pad:0,level:1,cool:0}];gameOver=false;ability=1;updateDeck();refreshHud();return}if(active)return;active=true;spawnTotal=wave===5?9:7+Math.min(wave,6);spawnLeft=spawnTotal;spawned=0;spawnTimer=.45;playTone(270,.16);refreshHud();showToast(`Wave ${String(wave).padStart(2,'0')} · enemies approaching`)}
function spawnEnemy(){const boss=wave%5===0&&spawned===spawnTotal-1,hp=(24+wave*11)*(boss?8:1);enemies.push({id:Math.random()*1e8,t:0,hp,max:hp,speed:boss?25:34+Math.min(wave*1.6,14),boss,armor:boss?.25:0});spawnLeft--;spawned++;if(boss)showToast('A powerful presence enters the crossing…')}
function shoot(t,e){const a=pos(pads[t.pad]),p=along(e.t);projectiles.push({x:a.x,y:a.y-10,tx:p.x,ty:p.y,color:t.hero.color,life:.13});e.hp-=t.hero.dmg*t.level*(1-e.armor);fx.push({x:p.x,y:p.y,r:e.boss?19:10,life:.24,max:.24,color:t.hero.color,text:t.hero.symbol});playTone(520+Math.random()*180,.035)}
function castAbility(){if(!ability||!enemies.length)return;ability--;const damage=45+wave*9;enemies.forEach(e=>{e.hp-=damage;let p=along(e.t);fx.push({x:p.x,y:p.y,r:e.boss?30:18,life:.48,max:.48,color:'#a890ff',text:'✧'})});fx.push({x:W*.5,y:H*.35,r:75,life:.7,max:.7,color:'#e6c682',text:'☄'});playTone(740,.2);showToast(`STARFALL · ${damage} astral damage`);refreshHud()}

