  function castAbility(){if(!ability||!enemies.length)return;ability--;const damage=45+wave*9;enemies.forEach(e=>{e.hp-=damage;let p=along(e.t);fx.push({x:p.x,y:p.y,r:e.boss?30:18,life:.48,max:.48,color:'#a890ff',text:'✧'})});fx.push({x:W*.5,y:H*.35,r:75,life:.7,max:.7,color:'#e6c682',text:'☄'});playTone(740,.2);showToast(`STARFALL · ${damage} astral damage`);refreshHud()}
  let audio;
  function playTone(freq,duration){if(!sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch(_){}}
  function update(dt){elapsed+=dt;const step=dt*speed;if(active){spawnTimer-=step;if(spawnLeft>0&&spawnTimer<=0){spawnEnemy();spawnTimer=wave>=4?.62:.82}const pts=routePoints(),path=metrics(pts).total;for(const e of enemies){e.t+=e.speed*step/path;if(e.t>=1){e.leaked=true;lives=Math.max(0,lives-(e.boss?5:1));fx.push({x:W*.94,y:H*.35,r:28,life:.4,max:.4,color:'#f0788f',text:'♥'})}}enemies=enemies.filter(e=>!e.leaked);if(lives<=0){active=false;gameOver=true;showToast('The gate has fallen · retry the mission');playTone(150,.35)}for(const t of towers){t.cool-=step;if(t.cool<=0){const origin=pos(pads[t.pad]),target=enemies.filter(e=>{const p=along(e.t);return Math.hypot(p.x-origin.x,p.y-origin.y)<t.hero.range}).sort((a,b)=>b.t-a.t)[0];if(target){shoot(t,target);t.cool=t.hero.rate/Math.min(t.level,2)}}}for(const e of enemies){if(e.hp<=0){const p=along(e.t);coins+=e.boss?100:12;fx.push({x:p.x,y:p.y,r:e.boss?30:16,life:.35,max:.35,color:'#e9c779',text:'✦'});e.dead=true}}enemies=enemies.filter(e=>!e.dead);if(active&&spawnLeft===0&&enemies.length===0){active=false;coins+=45+wave*8;ability=Math.min(2,ability+1);showToast(`Wave ${wave} cleared · +${45+wave*8} stardust`);wave++;if(wave>8){wave=8;gameOver=true;showToast('ASTRAL FRONTIER CLEARED · the gate is safe')}playTone(640,.16)}}for(const p of projectiles)p.life-=dt;projectiles=projectiles.filter(p=>p.life>0);for(const f of fx)f.life-=dt;fx=fx.filter(f=>f.life>0);refreshHud()}
  function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}
  function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false')}
  function closeModal(){$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true')}
  function openDeck(){const options=heroes.map(h=>`<button class="roster-option ${deck.includes(h.id)?'active':''}" data-hero="${h.id}"><span class="mini-avatar" style="background:${h.color}22;color:${h.color}">${h.symbol}</span><span><b>${h.name} · ${h.title}</b><small>${h.role} · ${h.cost} stardust</small></span></button>`).join('');openModal(`<span class="eyebrow">GUARDIAN ROSTER · ${deck.length} / 5</span><h2>Build your battle deck</h2><p>Choose up to five guardians. Deployed guardians stay on the field if removed from your deck.</p><div class="roster-grid">${options}</div><button class="modal-action" id="deckDone">DONE · ${deck.length} SELECTED</button>`);document.querySelectorAll('[data-hero]').forEach(btn=>btn.onclick=()=>{const id=btn.dataset.hero;if(deck.includes(id)){if(deck.length<=1){showToast('Keep at least one guardian in your deck');return}deck=deck.filter(x=>x!==id);if(selected===id)selected=deck[0]}else if(deck.length<5)deck.push(id);else{showToast('Your battle deck is full');return}openDeck();updateDeck()});$('#deckDone').onclick=()=>{closeModal();updateDeck()}}
  function openMap(){const chapters=[['Moonlit Crossing','You are here · Frontier 01'],['Glassfall Ruins','Unlocks after wave 3'],['The Astral Spire','A signal beyond the veil'],['Hollow Crown','Chapter boss · locked']];openModal(`<span class="eyebrow">ASTERIA · CAMPAIGN MAP</span><h2>The Shattered Gate</h2><p>Follow the rift trail through the frontier. Your current mission progress is saved locally for this visit.</p><div class="map-grid">${chapters.map((c,i)=>`<div class="map-level ${i===0?'current':''}"><b>${i===0?'✦ ':''}${c[0]}</b><small>${i===0?`Wave ${wave} · ${lives} gate HP`:c[1]}</small></div>`).join('')}</div><button class="modal-action" id="mapDone">RETURN TO BATTLE</button>`);$('#mapDone').onclick=closeModal}
  function openHelp(){openModal(`<span class="eyebrow">FIELD MANUAL · QUICK START</span><h2>Hold the crossing</h2><p>Select a guardian from your battle deck, then tap an open glowing landing circle. Guardians automatically attack enemies in range.</p><div class="map-grid"><div class="map-level"><b>Deploy & upgrade</b><small>Spend stardust to place heroes. Select a deployed hero and press U to upgrade; press X to sell it.</small></div><div class="map-level"><b>Starfall · Q</b><small>Use the astral burst to damage every enemy on the trail. Clear waves to earn stardust and recharge it.</small></div><div class="map-level"><b>Speed · 1× / 2×</b><small>Adjust the battle pace at any time. Keep riftborn away from the gate to protect your HP.</small></div><div class="map-level"><b>Boss waves</b><small>A powerful armored enemy appears every fifth wave. Focus your strongest guardians on it.</small></div></div><button class="modal-action" id="helpDone">UNDERSTOOD</button>`);$('#helpDone').onclick=closeModal}
  function upgrade(){if(!selectedTower){showToast('Select a deployed guardian first');return}const cost=90*selectedTower.level;if(selectedTower.level>=3){showToast('This guardian is already at maximum rank');return}if(coins<cost){showToast(`Need ${cost-coins} more stardust to upgrade`);return}coins-=cost;selectedTower.level++;selectedTower.cool=0;playTone(680,.13);refreshHud();showToast(`${selectedTower.hero.name} upgraded to rank ${selectedTower.level}`)}
  function sell(){if(!selectedTower){showToast('Select a deployed guardian first');return}const tower=selectedTower;if(tower.pad===0&&tower.hero.id==='aiko'){showToast('The Dawnblade is bound to this crossing');return}coins+=Math.floor(tower.hero.cost*.65);towers=towers.filter(t=>t!==tower);selectedTower=null;updateDeck();refreshHud();showToast('Guardian recalled · stardust refunded')}
  function selectPad(i){const tower=towers.find(t=>t.pad===i);if(tower){selectedTower=tower;selected=tower.hero.id;updateDeck();showToast(`${tower.hero.name} · rank ${tower.level} — U upgrade · X sell`)}else{selectedTower=null;deploy(i)}}
  canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;hoverPad=pads.findIndex(p=>Math.hypot(p.x*W-x,p.y*H-y)<23)});
  canvas.addEventListener('pointerleave',()=>hoverPad=-1);
  canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,i=pads.findIndex(p=>Math.hypot(p.x*W-x,p.y*H-y)<26);if(i>=0){e.preventDefault();selectPad(i)}});
  $('#launchBtn').addEventListener('click',startWave);$('#abilityBtn').addEventListener('click',castAbility);$('#speedBtn').addEventListener('click',()=>{speed=speed===1?2:1;$('#speedBtn').innerHTML=`${speed===1?'▶':'»'} <b>${speed}×</b>`});$('#soundBtn').addEventListener('click',()=>{sound=!sound;$('#soundBtn').textContent=sound?'♫':'♩';$('#soundBtn').classList.toggle('muted',!sound);if(sound)playTone(520,.08)});$('#helpBtn').addEventListener('click',openHelp);$('#deckBtn').addEventListener('click',openDeck);$('#mapBtn').addEventListener('click',openMap);$('#modalClose').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key.toLowerCase()==='q')castAbility();if(e.key.toLowerCase()==='u')upgrade();if(e.key.toLowerCase()==='x')sell();if(e.code==='Space'){e.preventDefault();if(!active)startWave()}});
  updateDeck();refreshHud();requestAnimationFrame(frame);
})();

